// VULNERABLE — writes raw user input to DOM
document.getElementById('name').innerHTML = userInput;

// SAFE — treats the value as plain text, not HTML
document.getElementById('name').textContent = userInput;

// VULNERABLE — user input embedded in SQL string
const query = `SELECT * FROM users WHERE name = '${userInput}'`;

// SAFE — parameterized query keeps data separate from code
const query = 'SELECT * FROM users WHERE name = $1';
await db.query(query, [userInput]);

