// HTML body context — encode to entities
const safe = userInput
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
element.innerHTML = safe;   // data, not markup

